    static std::unique_ptr<Shape> create(const std::string& name) {
        auto it = table().find(name);
        if (it == table().end()) throw std::invalid_argument{"unknown shape: " + name};
        return it->second();
    }
private:
    static std::unordered_map<std::string, Creator>& table() {   // Meyers: lazy, no init-order fiasco
        static std::unordered_map<std::string, Creator> t;
